CREATE TYPE public.market_role AS ENUM ('farmer','buyer');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL CHECK(char_length(trim(display_name)) BETWEEN 1 AND 100), contact text NOT NULL DEFAULT '' CHECK(char_length(contact)<=30), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profile_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid());
CREATE POLICY profile_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE TABLE public.user_roles (user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, role public.market_role NOT NULL);
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY role_read ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.has_market_role(wanted public.market_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role=wanted) $$;
REVOKE ALL ON FUNCTION public.has_market_role(public.market_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_market_role(public.market_role) TO authenticated;
CREATE FUNCTION public.market_signup() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
 IF COALESCE(NEW.raw_user_meta_data->>'role','') NOT IN ('farmer','buyer') THEN RAISE EXCEPTION 'Choose Farmer or Buyer'; END IF;
 INSERT INTO public.profiles(id,display_name,contact) VALUES(NEW.id,trim(COALESCE(NEW.raw_user_meta_data->>'display_name','')),COALESCE(NEW.raw_user_meta_data->>'contact',''));
 INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,(NEW.raw_user_meta_data->>'role')::public.market_role); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.market_signup() FROM PUBLIC;
CREATE TRIGGER market_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.market_signup();
CREATE TABLE public.listings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), seller_id uuid NOT NULL REFERENCES public.profiles(id), waste_type text NOT NULL CHECK(waste_type IN ('paddy_straw','coconut_husk','other_crop_residue')), quantity numeric NOT NULL CHECK(quantity>0 AND quantity<=1000000 AND quantity::text NOT IN ('NaN','Infinity','-Infinity')), unit text NOT NULL CHECK(unit IN ('kg','quintal','tonne')), price numeric NOT NULL CHECK(price>=0 AND price<=10000000 AND price::text NOT IN ('NaN','Infinity','-Infinity')), location text NOT NULL CHECK(char_length(trim(location)) BETWEEN 1 AND 120), description text NOT NULL CHECK(char_length(trim(description)) BETWEEN 1 AND 1000), photo text NOT NULL DEFAULT '' CHECK(char_length(photo)<=500), seller_name text NOT NULL CHECK(char_length(trim(seller_name)) BETWEEN 1 AND 100), seller_contact text NOT NULL CHECK(seller_contact ~ '^\+91[6-9][0-9]{9}$'), status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','sold','deleted')), is_demo boolean NOT NULL DEFAULT false CHECK(is_demo=false), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), CHECK(quantity*(CASE unit WHEN 'quintal' THEN 100 WHEN 'tonne' THEN 1000 ELSE 1 END)<=1000000));
GRANT SELECT ON public.listings TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.listings TO authenticated; GRANT ALL ON public.listings TO service_role;
ALTER TABLE public.listings ENABLE ROW LEVEL SECURITY;
CREATE POLICY listing_public ON public.listings FOR SELECT TO anon,authenticated USING(status='published');
CREATE POLICY listing_owner_read ON public.listings FOR SELECT TO authenticated USING(seller_id=auth.uid());
CREATE POLICY listing_create ON public.listings FOR INSERT TO authenticated WITH CHECK(seller_id=auth.uid() AND public.has_market_role('farmer') AND NOT is_demo);
CREATE POLICY listing_edit ON public.listings FOR UPDATE TO authenticated USING(seller_id=auth.uid() AND public.has_market_role('farmer')) WITH CHECK(seller_id=auth.uid() AND public.has_market_role('farmer') AND NOT is_demo);
CREATE POLICY listing_delete ON public.listings FOR DELETE TO authenticated USING(seller_id=auth.uid() AND public.has_market_role('farmer'));
CREATE FUNCTION public.listing_identity_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND (NEW.id<>OLD.id OR NEW.seller_id<>OLD.seller_id OR NEW.created_at<>OLD.created_at) THEN RAISE EXCEPTION 'Listing identity cannot change'; END IF; NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER listing_identity BEFORE UPDATE ON public.listings FOR EACH ROW EXECUTE FUNCTION public.listing_identity_guard();
CREATE TABLE public.inquiries (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), listing_id uuid NOT NULL REFERENCES public.listings(id) ON DELETE CASCADE, buyer_id uuid NOT NULL REFERENCES public.profiles(id), buyer_name text NOT NULL CHECK(char_length(trim(buyer_name)) BETWEEN 1 AND 100), contact text NOT NULL CHECK(char_length(trim(contact)) BETWEEN 1 AND 255), message text NOT NULL CHECK(char_length(trim(message)) BETWEEN 1 AND 1000), status text NOT NULL DEFAULT 'new' CHECK(status IN ('new','read','closed')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.inquiries TO authenticated; GRANT ALL ON public.inquiries TO service_role;
ALTER TABLE public.inquiries ENABLE ROW LEVEL SECURITY;
CREATE POLICY inquiry_read ON public.inquiries FOR SELECT TO authenticated USING(buyer_id=auth.uid() OR EXISTS(SELECT 1 FROM public.listings l WHERE l.id=listing_id AND l.seller_id=auth.uid()));
CREATE POLICY inquiry_create ON public.inquiries FOR INSERT TO authenticated WITH CHECK(buyer_id=auth.uid() AND public.has_market_role('buyer') AND status='new' AND EXISTS(SELECT 1 FROM public.listings l WHERE l.id=listing_id AND l.status='published' AND l.seller_id<>auth.uid()));
CREATE POLICY inquiry_update ON public.inquiries FOR UPDATE TO authenticated USING(EXISTS(SELECT 1 FROM public.listings l WHERE l.id=listing_id AND l.seller_id=auth.uid())) WITH CHECK(EXISTS(SELECT 1 FROM public.listings l WHERE l.id=listing_id AND l.seller_id=auth.uid()));
CREATE FUNCTION public.inquiry_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
 IF NOT (NEW.contact ~ '^\+?([0-9 ()-]){10,30}$' OR NEW.contact ~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$') THEN RAISE EXCEPTION 'Invalid buyer contact'; END IF;
 IF TG_OP='UPDATE' AND (NEW.id<>OLD.id OR NEW.listing_id<>OLD.listing_id OR NEW.buyer_id<>OLD.buyer_id OR NEW.buyer_name<>OLD.buyer_name OR NEW.contact<>OLD.contact OR NEW.message<>OLD.message OR NEW.created_at<>OLD.created_at) THEN RAISE EXCEPTION 'Only inquiry status can change'; END IF; RETURN NEW; END $$;
CREATE TRIGGER inquiry_validation BEFORE INSERT OR UPDATE ON public.inquiries FOR EACH ROW EXECUTE FUNCTION public.inquiry_guard();
CREATE INDEX listings_published ON public.listings(status,created_at DESC); CREATE INDEX listings_seller ON public.listings(seller_id); CREATE INDEX inquiries_buyer ON public.inquiries(buyer_id); CREATE INDEX inquiries_listing ON public.inquiries(listing_id);
